implements IModPlugin {
    private static final ResourceLocation ID = Copycats.asResource("jei_plugin");
    public static IIngredientManager MANAGER;

    @NotNull
    public ResourceLocation getPluginUid() {
        return ID;
    }

    public void onRuntimeAvailable(IJeiRuntime jeiRuntime) {
        MANAGER = jeiRuntime.getIngredientManager();
    }

    public static void refreshItemList() {
        if (MANAGER != null) {
            MANAGER.removeIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.DECORATIVE.stream().map(ItemProviderEntry::asStack).collect(Collectors.toList()));
            MANAGER.removeIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.FUNCTIONAL.stream().map(ItemProviderEntry::asStack).collect(Collectors.toList()));
            MANAGER.addIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.DECORATIVE.stream().filter(x -> FeatureToggle.isEnabled(x.getId())).map(ItemProviderEntry::asStack).collect(Collectors.toList()));
            MANAGER.addIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.FUNCTIONAL.stream().filter(x -> FeatureToggle.isEnabled(x.getId())).map(ItemProviderEntry::asStack).collect(Collectors.toList()));
        }
    }
}

